{% var leafRows = data.filter(function(r) { return !r.is_total_row; }); %}
{% var taskSet = {}, todoSet = {}, projectSet = {}, customerSet = {}, totalHours = 0; %}
{% leafRows.forEach(function(r) { if (r.task) { taskSet[r.task] = 1; } if (r.todo) { todoSet[r.todo] = 1; } if (r.project) { projectSet[r.project] = 1; } if (r.customer) { customerSet[r.customer] = 1; } totalHours += flt(r.total_hours); }); %}
{% var taskCount = Object.keys(taskSet).length; %}
{% var todoCount = Object.keys(todoSet).length; %}
{% var projectNames = Object.keys(projectSet); %}
{% var customerNames = Object.keys(customerSet); %}
{% var projectLabel = filters.project ? filters.project : (projectNames.length ? projectNames.join(", ") : "-"); %}
{% var customerLabel = filters.customer ? filters.customer : (customerNames.length ? customerNames.join(", ") : "-"); %}
{% var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]; %}
{% function iwex_fmt_full(s) { if (!s) { return "-"; } var d = new Date(s); if (isNaN(d.getTime())) { return "-"; } var dd = ("0" + d.getDate()).slice(-2); return dd + "-" + MONTHS[d.getMonth()] + ", " + d.getFullYear(); } %}
{% function iwex_fmt_short(s) { if (!s) { return "-"; } var d = new Date(s); if (isNaN(d.getTime())) { return "-"; } var dd = ("0" + d.getDate()).slice(-2); return dd + "-" + MONTHS[d.getMonth()]; } %}
{% function iwex_row_date(r) { return iwex_fmt_full(r.period || r.period_day || r.period_week); } %}
{% var rowDates = []; %}
{% leafRows.forEach(function(r) { var d = r.period || r.period_day || r.period_week; if (d) { rowDates.push(d); } }); %}
{% rowDates.sort(); %}
{% var rangeStart = rowDates.length ? rowDates[0] : filters.from_date; %}
{% var rangeEnd = rowDates.length ? rowDates[rowDates.length - 1] : filters.to_date; %}
{% var dateRangeLabel = "-"; %}
{% if (rangeStart && rangeEnd) { %}
{% dateRangeLabel = iwex_fmt_short(rangeStart) + " to " + iwex_fmt_short(rangeEnd) + ", " + new Date(rangeEnd).getFullYear(); %}
{% } %}
{% var createdOnLabel = iwex_fmt_full(frappe.datetime.now_date()); %}
{% var totalWorkedLabel = (Math.round(totalHours * 100) / 100) + " " + __("hours"); %}
<div class="iwex-report-print">
	<div class="iwex-report-header">
		<div class="iwex-report-logo"><img src="/assets/iwexclock/images/iwex-logo.png" alt="IWEX"></div>
		<div class="iwex-report-title">{{ __("iWEXClock Report") }}</div>
		<div class="iwex-report-company"><a href="https://iwex.in">https://iwex.in</a></div>
	</div>
	<table class="iwex-report-info">
		<tbody>
			<tr>
				<td><strong>{{ __("CUSTOMER") }}:</strong> {{ customerLabel }}</td>
				<td><strong>{{ __("TASKS") }}:</strong> {{ taskCount }}</td>
				<td><strong>{{ __("CREATED ON") }}:</strong> {{ createdOnLabel }}</td>
			</tr>
			<tr>
				<td><strong>{{ __("PROJECT ID") }}:</strong> {{ projectLabel }}</td>
				<td><strong>{{ __("TODOS") }}:</strong> {{ todoCount }}</td>
				<td><strong>{{ __("DATE RANGE") }}:</strong> {{ dateRangeLabel }}</td>
			</tr>
			<tr>
				<td class="iwex-info-total-cell" colspan="3">{{ __("TOTAL WORKED") }}: {{ totalWorkedLabel }}</td>
			</tr>
		</tbody>
	</table>
	<table class="iwex-report-table">
		<thead>
			<tr>
				<th class="iwex-col-date">{{ __("Date") }}</th>
				<th class="iwex-col-auto">{{ __("Customer") }}</th>
				<th class="iwex-col-auto">{{ __("Project") }}</th>
				<th class="iwex-col-auto">{{ __("Task") }}</th>
				<th class="iwex-col-auto">{{ __("Todo") }}</th>
				<th class="iwex-col-center">{{ __("Duration") }}</th>
				<th class="iwex-col-center">{{ __("Sessions") }}</th>
				<th class="iwex-col-auto">{{ __("User") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in data %}
			{% if (!row.is_total_row) { %}
			<tr>
				<td class="iwex-col-date">{{ iwex_row_date(row) }}</td>
				<td class="iwex-col-auto">{{ row.customer || "" }}</td>
				<td class="iwex-col-auto">{{ row.project || "-" }}</td>
				<td class="iwex-col-auto">{{ row.task || "-" }}</td>
				<td class="iwex-col-auto">{{ row.todo || "-" }}</td>
				<td class="iwex-col-center">{{ row.total_duration || "-" }}</td>
				<td class="iwex-col-center">{{ row.sessions != null ? row.sessions : "-" }}</td>
				<td class="iwex-col-auto">{{ row.user || "-" }}</td>
			</tr>
			{% } %}
			{% endfor %}
		</tbody>
	</table>
</div>

css:
.iwex-report-print {
	font-family: inherit;
	color: #1a1a1a;
}

.iwex-report-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	border-bottom: 2px solid #1f2a44;
	padding-bottom: 10px;
	margin-bottom: 14px;
}

.iwex-report-logo {
	flex: 1;
}

.iwex-report-logo img {
	height: 34px;
	width: auto;
	display: block;
}

.iwex-report-title {
	font-size: 16px;
	font-weight: 600;
	color: #1f2a44;
	flex: 2;
	text-align: center;
}

.iwex-report-company {
	font-size: 12px;
	font-weight: 600;
	color: #1f2a44;
	flex: 1;
	text-align: right;
}

.iwex-report-company a {
	color: #1a73e8;
	text-decoration: none;
}

table.iwex-report-info {
	width: 100%;
	table-layout: fixed;
	border-collapse: collapse;
	border: none;
	margin-bottom: 16px;
	font-size: 11px;
}

table.iwex-report-info td {
	border: none;
	padding: 6px 10px;
	width: 33.33%;
}

table.iwex-report-info td:not([colspan]):nth-child(2) {
	text-align: center;
}

table.iwex-report-info td:not([colspan]):nth-child(3) {
	text-align: right;
}

table.iwex-report-info tr:nth-child(1) td,
table.iwex-report-info tr:nth-child(2) td {
	border-bottom: 1px solid #dde0e6;
}

table.iwex-report-info .iwex-info-total-cell {
	text-align: center;
	font-weight: 700;
	color: #1f2a44;
}

table.iwex-report-table {
	width: 100%;
	border-collapse: collapse;
	font-size: 11px;
}

table.iwex-report-table th {
	background-color: #a5aab4;
	color: #1f2a44;
	text-align: left;
	padding: 7px 10px;
	font-weight: 600;
	border: none;
	border-bottom: 1px solid #8b93a3;
}

table.iwex-report-table td {
	padding: 6px 10px;
	border: none;
	border-bottom: 1px solid #dde0e6;
}

table.iwex-report-table tbody tr:nth-child(even) {
	background-color: #f8f9fb;
}

table.iwex-report-table .iwex-col-center {
	text-align: center;
}

table.iwex-report-table .iwex-col-date {
	width: 100px;
	white-space: nowrap;
}

table.iwex-report-table .iwex-col-auto {
	width: auto;
}
